// External plugin contract — wire protocol between core and plugin (#132).
//
// Two directions:
//   plugin → core: registration + the two API surfaces (scoped / instance),
//                  capability invocation, realtime invalidation.
//   core → plugin: screen renders, actions, webhooks, tool execution,
//                  exchange hooks, health, purge.
// Every core→plugin request is HMAC-signed (see external-signing.ts); the
// plugin must reject unsigned or replayed calls.

import type { UiActionResult, UiScreen } from './external-ui';
import type {
  ExternalContractVersion,
  ExternalPluginManifest,
} from './external-manifest';

// ── Access classes (decision #3) ────────────────────────────────────────────
// delegated           — short-lived token bound to the requesting user.
// background-scoped   — no user; one scope (per-scope model: one per scope).
// background-instance — no user; instance surface only.
export type ExternalAccessClass =
  | 'delegated'
  | 'background-scoped'
  | 'background-instance';

// ── Plugin → core: registration ─────────────────────────────────────────────

export const EXTERNAL_REGISTER_PATH = '/api/external/register';

export interface ExternalRegisterRequest {
  // One-time install token generated by the admin — or the previously issued
  // plugin secret when an already-installed plugin re-announces after restart
  // (the update path; decision #15).
  installToken?: string;
  pluginSecret?: string;
  manifest: ExternalPluginManifest;
  // Base URL the core calls back on (renders, webhooks, hooks). Must be
  // reachable from the core container.
  baseUrl: string;
}

export type ExternalRegisterResponse =
  | {
      status: 'pending' | 'active';
      // Issued on first successful registration; the plugin persists it and
      // authenticates every later call and re-registration with it.
      pluginSecret?: string;
      contract: ExternalContractVersion;
    }
  | { error: string };

// ── Core → plugin: render protocol ──────────────────────────────────────────
// Paths are relative to the plugin's registered baseUrl.

export const PLUGIN_HEALTH_PATH = '/mk/health';
export const PLUGIN_RENDER_PATH = '/mk/render';
export const PLUGIN_ACTION_PATH = '/mk/action';
export const PLUGIN_WEBHOOK_PATH = '/mk/events';
export const PLUGIN_TOOL_PATH = '/mk/tool';
export const PLUGIN_RESOLVE_REF_PATH = '/mk/resolve-ref';
export const PLUGIN_EXPORT_PATH = '/mk/exchange/export';
export const PLUGIN_IMPORT_PATH = '/mk/exchange/import';
export const PLUGIN_CAPABILITY_PATH = '/mk/capability';
export const PLUGIN_PURGE_PATH = '/mk/purge';

// Common request context: who the render/action/tool call is for. `scopeId`
// is an opaque stable id ('' while multiuser is off — treated as the single
// implicit scope); `locale` drives i18n params the plugin may embed.
export interface ExternalCallContext {
  scopeId: string;
  locale: string;
  // WHO is calling, as far as a plugin is allowed to know (contract 1.4).
  //
  // Opaque, stable, and salted per plugin: the same person is the same string
  // to this plugin forever, a different string to every other plugin, and no
  // string can be worked back to a user. That is what lets a plugin separate
  // "my bookings" from "everyone's" inside one shared scope without learning
  // anyone's identity. Absent on background calls, which have no user.
  userRef?: string;
  // Short-lived delegated token the plugin uses to call the core back as the
  // user. Absent on background invocations (webhooks, cron-driven calls).
  delegatedToken?: string;
}

export interface ExternalRenderRequest {
  screen: string;
  params: Record<string, string>;
  // What the user has typed so far, when the render was triggered by a field
  // declaring `reloadOnChange` (contract 1.2). Absent on a first render.
  form?: Record<string, string | number | boolean>;
  context: ExternalCallContext;
}

export type ExternalRenderResponse = { screen: UiScreen } | { error: string };

export interface ExternalActionRequest {
  screen: string;
  action: string;
  params: Record<string, string | number | boolean>;
  // Form field values keyed by field name, when the action came from a form.
  form?: Record<string, string | number | boolean>;
  context: ExternalCallContext;
}

export type ExternalActionResponse = UiActionResult | { error: string };

// ── Core → plugin: webhooks (decision #10) ──────────────────────────────────

// The envelope is deliberately thin: an event says WHAT TO LOOK AT, never
// what to do and never what the data now is. Handlers re-read current state
// by `ref` through the API surfaces with their own token — that model is what
// makes at-least-once delivery and the absence of ordering safe (see
// docs/external-events.md).
export interface ExternalWebhookEvent {
  eventId: string;
  type: string;
  // Version of this envelope shape (EXTERNAL_EVENT_SCHEMA_VERSION). Bumped
  // only for an incompatible change of the envelope itself; subscribers MUST
  // reject a version they do not know instead of half-parsing it.
  schemaVersion: number;
  scopeId: string;
  // Canonical mk:// reference of the affected entity, when one exists.
  ref?: string;
  // Names of the fields that changed — never their values: a value delivered
  // without an ordering guarantee may already be stale, so the envelope makes
  // relying on one syntactically impossible.
  changed?: string[];
  occurredAt: string;
}

// Built-in lifecycle event types every plugin may subscribe to.
export const EXTERNAL_EVENT_SCOPE_DELETED = 'core.scope-deleted';
export const EXTERNAL_EVENT_PLUGIN_ENABLED = 'core.plugin-enabled';
export const EXTERNAL_EVENT_PLUGIN_DISABLED = 'core.plugin-disabled';

// ── Core → plugin: agent tools (decision #7) ────────────────────────────────

export interface ExternalToolRequest {
  tool: string;
  args: Record<string, unknown>;
  context: ExternalCallContext;
}

export type ExternalToolResponse = { result: unknown } | { error: string };

// ── Core → plugin: ORef resolution ──────────────────────────────────────────

export interface ExternalResolveRefRequest {
  entityType: string;
  entityId: string;
  context: ExternalCallContext;
}

export type ExternalResolveRefResponse =
  | { name: string; breadcrumb?: string[] }
  | { error: string };

// ── Plugin → core: realtime invalidation (decision #11) ─────────────────────

export const EXTERNAL_NOTIFY_CHANGED_PATH = '/api/external/notify-changed';

export interface ExternalNotifyChangedRequest {
  screen: string;
  scopeId?: string;
}

// ── Plugin → core: capability invocation (decision #13) ─────────────────────

export const EXTERNAL_INVOKE_CAPABILITY_PATH = '/api/external/capability';

export interface ExternalInvokeCapabilityRequest {
  capability: string;
  method: string;
  // Opaque JSON relayed to the owner; the core validates nothing here beyond
  // the permission grant (documented authors' responsibility).
  args: unknown[];
}

export type ExternalInvokeCapabilityResponse =
  | { result: unknown }
  | { error: string };

// ── Core → plugin: exchange hooks (decision #12) ────────────────────────────
// Both hooks stream: export responds with an opaque binary body; import
// receives one. The blob must be self-contained and versioned by the plugin —
// `import` must fail gracefully on an incompatible blob version.

export interface ExternalExportRequest {
  scopeId: string;
}

// ── Health ──────────────────────────────────────────────────────────────────

export interface ExternalHealthResponse {
  ok: boolean;
  version: string;
}
